// Generated by the Salvo compiler: hash containers keyed by a named `hash`/`eq`.
//
// [cmp-carry] [col-membership] A `Set<T, ?hash, ?eq>` or `Map<K, V, ?hash, ?eq>`
// whose type *names* the pair its keys are kept by needs a container that will
// use them. The JVM's own `LinkedHashSet`/`LinkedHashMap` key off `hashCode` and
// `equals` with no slot for anything else, so these are the equivalents — and
// they are *only* used where a pair is named: a collection whose type names none
// is still a `LinkedHashMap`, which is what every Salvo program has always
// compiled to.
//
// They extend the JVM's abstract collections, so the emitted **type** is
// unchanged (`MutableMap<K, V>`, `MutableSet<T>`) and every operation the
// backend lowers — `put`, `get`, `containsKey`, `keys`, `size`, iteration —
// arrives through the interface. Which is why naming a hash costs this backend a
// construction site and nothing else.
//
// Representation, matching the Rust runtime's so the two agree observably
// [backend-parity]: entries live in a list in first-insertion order, and a bucket
// index maps a Salvo hash to the slots holding it. A removed slot becomes `null`
// so stored indices stay valid, and the list is compacted once the dead slots
// outnumber the live ones.
package salvo

class SalvoHashMap<K, V>(
    private val hashOf: (K) -> Long,
    private val eqOf: (K, K) -> Boolean,
) : AbstractMutableMap<K, V>() {
    private class Slot<K, V>(val key: K, var value: V)

    private val slots = ArrayList<Slot<K, V>?>()
    private val buckets = HashMap<Long, MutableList<Int>>()
    private var live = 0

    private fun slotOf(key: K): Int? {
        val bucket = buckets[hashOf(key)] ?: return null
        for (i in bucket) {
            val slot = slots[i]
            if (slot != null && eqOf(slot.key, key)) {
                return i
            }
        }
        return null
    }

    override fun put(key: K, value: V): V? {
        val at = slotOf(key)
        if (at != null) {
            val slot = slots[at]!!
            val old = slot.value
            // An overwrite keeps the key's original position, so iteration order
            // is stable under updates — `LinkedHashMap`'s rule, which the Rust
            // runtime follows too.
            slot.value = value
            return old
        }
        slots.add(Slot(key, value))
        buckets.getOrPut(hashOf(key)) { ArrayList() }.add(slots.size - 1)
        live += 1
        return null
    }

    override fun get(key: K): V? = slotOf(key)?.let { slots[it]!!.value }

    override fun containsKey(key: K): Boolean = slotOf(key) != null

    override fun remove(key: K): V? {
        val at = slotOf(key) ?: return null
        val slot = slots[at]!!
        slots[at] = null
        buckets[hashOf(slot.key)]?.remove(at)
        live -= 1
        compactIfSparse()
        return slot.value
    }

    private fun compactIfSparse() {
        if (slots.size <= 2 * live + 8) {
            return
        }
        val kept = slots.filterNotNull()
        slots.clear()
        slots.addAll(kept)
        buckets.clear()
        for ((i, slot) in slots.withIndex()) {
            buckets.getOrPut(hashOf(slot!!.key)) { ArrayList() }.add(i)
        }
    }

    override val size: Int
        get() = live

    override val entries: MutableSet<MutableMap.MutableEntry<K, V>>
        get() = object : AbstractMutableSet<MutableMap.MutableEntry<K, V>>() {
            override val size: Int
                get() = live

            override fun add(element: MutableMap.MutableEntry<K, V>): Boolean {
                throw UnsupportedOperationException()
            }

            override fun iterator(): MutableIterator<MutableMap.MutableEntry<K, V>> {
                val live = slots.filterNotNull()
                val inner = live.iterator()
                return object : MutableIterator<MutableMap.MutableEntry<K, V>> {
                    override fun hasNext(): Boolean = inner.hasNext()

                    override fun next(): MutableMap.MutableEntry<K, V> {
                        val slot = inner.next()
                        return object : MutableMap.MutableEntry<K, V> {
                            override val key: K
                                get() = slot.key
                            override val value: V
                                get() = slot.value

                            override fun setValue(newValue: V): V {
                                val old = slot.value
                                slot.value = newValue
                                return old
                            }
                        }
                    }

                    override fun remove() {
                        throw UnsupportedOperationException()
                    }
                }
            }
        }
}

class SalvoHashSet<T>(
    hashOf: (T) -> Long,
    eqOf: (T, T) -> Boolean,
) : AbstractMutableSet<T>() {
    // A set is a map to nothing, the same representation the Rust runtime uses,
    // so the two cannot drift apart on ordering or removal.
    private val entries = SalvoHashMap<T, Unit>(hashOf, eqOf)

    override fun add(element: T): Boolean {
        if (entries.containsKey(element)) {
            return false
        }
        entries.put(element, Unit)
        return true
    }

    override fun remove(element: T): Boolean = entries.remove(element) != null

    override fun contains(element: T): Boolean = entries.containsKey(element)

    override val size: Int
        get() = entries.size

    override fun iterator(): MutableIterator<T> {
        val keys = entries.keys.toList()
        val inner = keys.iterator()
        return object : MutableIterator<T> {
            override fun hasNext(): Boolean = inner.hasNext()
            override fun next(): T = inner.next()
            override fun remove() {
                throw UnsupportedOperationException()
            }
        }
    }
}
